{
  "claims": [
    {
      "claim_text": "WAL mode first appeared in SQLite 3.7.0.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states that the Write-Ahead Log (WAL) option became available beginning with version 3.7.0.",
      "citations": [
        {
          "index": 4,
          "quote": "Beginning with version 3.7.0 (2010-07-21), a new \"Write-Ahead Log\" option (hereafter referred to as \"WAL\") is available."
        }
      ]
    },
    {
      "claim_text": "journal_mode=WAL is persistent.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] explicitly states that PRAGMA journal_mode=WAL is persistent.",
      "citations": [
        {
          "index": 2,
          "quote": "Unlike the other journaling modes, PRAGMA journal_mode=WAL is persistent."
        }
      ]
    },
    {
      "claim_text": "Simply closing and reopening a WAL database is not enough to change its page size.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] states that a database closed and reopened remains in WAL mode, and passage [0] states that page_size cannot be changed while in WAL mode; together they entail that closing and reopening does not enable a page size change.",
      "citations": [
        {
          "index": 2,
          "quote": "If a process sets WAL mode, then closes and reopens the database, the database will come back in WAL mode."
        },
        {
          "index": 0,
          "quote": "It is not possible to change the page_size after entering WAL mode, either on an empty database or by using VACUUM or by restoring from a backup using the backup API."
        }
      ]
    },
    {
      "claim_text": "To change the page size, you have to switch back to a rollback journal mode first.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states that one must be in a rollback journal mode to change the page size.",
      "citations": [
        {
          "index": 0,
          "quote": "You must be in a rollback journal mode to change the page size."
        }
      ]
    },
    {
      "claim_text": "From version 3.7.0 until 3.22.0, reading a WAL-mode database required write access.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] states that write access was required to read a WAL-mode database until the constraint was relaxed in version 3.22.0, and passage [4] establishes that WAL mode began with version 3.7.0.",
      "citations": [
        {
          "index": 3,
          "quote": "In other words, write access was required in order to read a WAL-mode database. This constraint was relaxed beginning with SQLite version 3.22.0 (2018-01-22)."
        },
        {
          "index": 4,
          "quote": "Beginning with version 3.7.0 (2010-07-21), a new \"Write-Ahead Log\" option (hereafter referred to as \"WAL\") is available."
        }
      ]
    },
    {
      "claim_text": "SQLite's default page size is 4096 bytes.",
      "verdict": "UNSUPPORTED",
      "reasoning": "None of the passages mention any default page size value.",
      "citations": []
    },
    {
      "claim_text": "Converting a database to WAL fails if the VFS does not support the necessary shared-memory primitives.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] gives the VFS lacking support for the necessary shared-memory primitives as an example of when conversion to WAL could not be completed.",
      "citations": [
        {
          "index": 1,
          "quote": "If the conversion to WAL could not be completed (for example, if the VFS does not support the necessary shared-memory primitives) then the journaling mode will be unchanged"
        }
      ]
    },
    {
      "claim_text": "When conversion to WAL fails, the journal_mode pragma returns an error.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [1] states that on failed conversion the pragma returns a string containing the prior journaling mode (e.g., \"delete\"), not an error.",
      "citations": [
        {
          "index": 1,
          "quote": "the journaling mode will be unchanged and the string returned from the primitive will be the prior journaling mode (for example \"delete\")."
        }
      ]
    }
  ]
}
